fn ult(version, rnd, player, data, positioning_score, target) -> Option<Input>

// --- 게이트 1 (281): 내 챔피언 존재? ---
team = player.info.team            // PlayerState+0x930, 2 미만 아니면 panic_bounds_check
pos  = player.info.position.as_index()   // PlayerState+0x9c0 (entity.rs:580)
champ = data.cache.player_champion[team][pos]   // AbstractGameWithCache+0x1e0
if champ == null { return None }   // '?' 연산자, store -1

// --- 게이트 2 (282-283): 궁 쓸 수 있는 상태? ---
if !champ.can_ult() { return None }

// --- 게이트 3 (286): 궁 이펙트 존재? ---
// Entity::ult_effect() 인라인(entity.rs:1700-1701)
effect = if champ.level > 4 { &champ.ult_effect } else { &EMPTY_EFFECT }
if effect.casting == -1 { return None }   // Option<Effect>::None 니치

// --- 게이트 4 (288-289): 타깃 종류 적합? ---
if !effect.target.check(champ, target) { return None }   // CastingTarget::check

// --- 시전형태별 사전 사거리 검사 (293~313) ---
// out_of_range 로 빠지면 get_input_target 을 아예 시도하지 않고 곧장 재배치로 간다.
match effect.casting {
  CastingType::Position(1) => {                       // 296
    if (*effect.ty).vtable[0x118]() == true {         // 이름 미상 술어
      range = linear_cast_range_with_margin(effect, champ, target);   // 297
      if distance_sq(champ.x, champ.y, target.x, target.y) > range*range { goto REPOSITION }  // 299
    }
  }
  CastingType::Direction(2) => {                      // 310
    if (*effect.ty).vtable[0xf8]().0 == 1 {           // 이름 미상, {i64,i64} 반환
      range = linear_cast_range_with_margin(effect, champ, target);   // 311
      if distance_sq(champ.x, champ.y, target.x, target.y) > range*range { goto REPOSITION }  // 313
    }
  }
  _ => {}   // Targeting(0), None(3) 은 사전 검사 없음
}

// --- 실제 입력 생성 (325-326) ---
cd = champ.cooldown_reduce(true)
input_target = get_input_target(version, rnd, player, data, positioning_score, target, effect, cd)
if input_target != None { return Some(Input::Ult(input_target)) }   // tag 5, 페이로드 24B memcpy

REPOSITION:
// --- 가시성 판정 (328) : Entity::is_visible_from(target, champ) 인라인 ---
// TeamType::player_team() (entity.rs:1135-1137): Neutral(tag 1) 이면 판정 생략하고 visible 취급
visible = match champ.team {
   Neutral => true,
   Player(t) => target.visible_state[t] == VisibleState::Visible   // t<2 아니면 panic_bounds_check
}

if !visible {
   // (340) 안 보이면 타깃 좌표로 그냥 접근
   return safe_move_avoiding_enemy_well(version, player, data, champ, target.x, target.y)
}

// --- 보이면 '사거리 안쪽' 지점으로 접근 (329-338) ---
dx = champ.x - target.x                       // 329 (부호 있는 뺄셈)
dy = champ.y - target.y                       // 330
sz = isqrt(dx*dx + dy*dy)                     // 331  (sz==0 이면 div-by-zero panic)

// effect_range_with_radii(effect, champ, target) 인라인 (abstract_input.rs:190-192)
//   champ_r = if effect.casting == Targeting { champ.radius() } else { 0 }        // 191
//   Effect::range(effect, champ) = effect.range + champ.stat_buff_cached.range
//                                  + (champ.level-1)*effect.growth_range          // effect.rs:25-26
//   total = Effect::range(effect, champ) + champ_r
//           + effect.range_adjust(champ, target) + target.radius()                // 192
//   Entity::radius() = if radius_mult==0 { radius } else { radius*(radius_mult+100)/100 }  // entity.rs:1511-1515
from_distance = total.saturating_sub(150000)  // 333

x = target.x + from_distance*dx/sz            // 334 (sdiv)
y = target.y + from_distance*dy/sz            // 335
(x, y) = Game::adjust_position(context.map, context.setting, x, y)   // 336
return safe_move_avoiding_enemy_well(version, player, data, champ, x, y)   // 338
